//! Arithmetic-coded JPEGs (SOF9 / SOF10) through the JPEG session: header facts, every scale,
//! the row index (recorded while decoding or built separately) and region decodes. The
//! fixtures are generated by specular-jpeg's `tests/fixtures/make-arith.sh` (cjpeg
//! -arithmetic); the decoder itself is checked against djpeg in specular-jpeg's tests.

use specular_core::{CancelToken, PixelLayout, Raster};
use specular_decode::{DecodeRequest, Rect, Registry};
use std::path::PathBuf;

fn files() -> Vec<PathBuf> {
    let jpeg = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../formats/specular-jpeg");
    let mut v: Vec<PathBuf> = std::fs::read_dir(jpeg.join("tests/fixtures"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| {
            let n = p.file_name().unwrap().to_string_lossy();
            n.starts_with("arith_") && n.ends_with(".jpg")
        })
        .collect();
    // The fuzz seed whose gallery thumbnail failed (larger, 4:2:0, from tools/fuzz/make-seeds.sh).
    let seed = jpeg.join("fuzz/seeds/arith.jpg");
    if seed.is_file() {
        v.push(seed);
    }
    v.sort();
    assert!(v.len() >= 5, "arith fixtures missing: {v:?}");
    v
}

/// Plane `i` of `full` at `r`'s origin equals plane `i` of `r`.
fn assert_crop(full: &Raster, r: &Raster, what: &str) {
    assert_eq!(full.planes.len(), r.planes.len(), "{what}");
    for (i, (fp, rp)) in full.planes.iter().zip(&r.planes).enumerate() {
        let bpp = if r.layout == PixelLayout::Rgba { 4 } else { 1 };
        let (ox, oy) = (
            (r.origin.0 - full.origin.0) / rp.h_div.max(1) as u32,
            (r.origin.1 - full.origin.1) / rp.v_div.max(1) as u32,
        );
        for y in 0..rp.height as usize {
            let a = (oy as usize + y) * fp.stride + ox as usize * bpp;
            let b = y * rp.stride;
            let n = rp.width as usize * bpp;
            assert_eq!(
                &fp.data[a..a + n],
                &rp.data[b..b + n],
                "{what}: plane {i} row {y} (origins {:?} {:?}, {}×{})",
                full.origin,
                r.origin,
                rp.width,
                rp.height
            );
        }
    }
}

#[test]
fn session_paths() {
    let reg = Registry::new();
    let c = CancelToken::new();
    for p in files() {
        let name = p.file_name().unwrap().to_string_lossy().to_string();
        let data = std::fs::read(&p).unwrap();
        let s = reg.open_path(&p).unwrap();
        let info = s.info();
        assert!(
            info.coding.starts_with("arithmetic"),
            "{name}: {}",
            info.coding
        );
        assert_eq!(info.progressive, name.contains("prog"), "{name}");
        assert_eq!(info.scales, &[1, 2, 4, 8]);
        assert!(!s.regions_ready());

        // Every scale, plain: the planes of specular-jpeg's decode.
        let mut fulls = Vec::new();
        for scale in [1u32, 2, 4, 8] {
            let r = s.decode(&DecodeRequest::full(scale), &c).unwrap();
            assert!(!r.truncated, "{name} 1/{scale}");
            assert_eq!(
                (r.width, r.height),
                (info.width.div_ceil(scale), info.height.div_ceil(scale)),
                "{name} 1/{scale}"
            );
            let sc = match scale {
                1 => specular_jpeg::Scale::Full,
                2 => specular_jpeg::Scale::Half,
                4 => specular_jpeg::Scale::Quarter,
                _ => specular_jpeg::Scale::Eighth,
            };
            let d = specular_jpeg::decode(
                &data,
                &specular_jpeg::DecodeOptions {
                    scale: sc,
                    ..Default::default()
                },
            )
            .unwrap();
            for (rp, dp) in r.planes.iter().zip(&d.planes) {
                for y in 0..dp.height as usize {
                    let n = dp.width as usize;
                    assert_eq!(
                        &rp.data[y * rp.stride..y * rp.stride + n],
                        &dp.data[y * dp.stride..y * dp.stride + n],
                        "{name} 1/{scale} row {y}"
                    );
                }
            }
            fulls.push(r);
        }

        // A whole-image level that prepares regions: sequential files record the index while
        // decoding; progressive ones build it in a separate pass (`prepare_regions`).
        let s = reg.open_path(&p).unwrap();
        let req = DecodeRequest {
            prepare_regions: true,
            ..DecodeRequest::full(2)
        };
        let r = s.decode(&req, &c).unwrap();
        assert_crop(&fulls[1], &r, &format!("{name} prepare level"));
        assert_eq!(s.regions_ready(), !info.progressive, "{name}");
        s.prepare_regions(&c).unwrap();
        assert!(s.regions_ready(), "{name}");
        assert!(s.memory_bytes() > 0, "{name}");

        // Regions with the index, and without it on a fresh session: crops of the full decode.
        let fresh = reg.open_path(&p).unwrap();
        for (k, scale) in [1u32, 2, 4, 8].into_iter().enumerate() {
            let (w, h) = (fulls[k].width, fulls[k].height);
            for rect in [
                Rect {
                    x: w / 3,
                    y: h / 3,
                    w: (w / 3).max(1),
                    h: (h / 4).max(1),
                },
                Rect {
                    x: w - 1,
                    y: h - 1,
                    w: 1,
                    h: 1,
                },
            ] {
                let req = DecodeRequest {
                    region: Some(rect),
                    ..DecodeRequest::full(scale)
                };
                let what = format!("{name} 1/{scale} {rect:?}");
                let a = s.decode(&req, &c).unwrap();
                assert!(a.origin.0 <= rect.x && a.origin.1 <= rect.y, "{what}");
                assert!(
                    a.origin.0 + a.width >= rect.x + rect.w
                        && a.origin.1 + a.height >= rect.y + rect.h,
                    "{what}"
                );
                assert_crop(&fulls[k], &a, &what);
                let b = fresh.decode(&req, &c).unwrap();
                assert_crop(&fulls[k], &b, &format!("{what} (no index)"));
            }
            // The memory the session asks for covers at least the output.
            let m = s.decode_memory(&DecodeRequest::full(scale));
            assert!(m >= fulls[k].memory_bytes() as u64, "{name} 1/{scale}: {m}");
        }
    }
}

/// Cut-short files open and show what is there, flagged as truncated.
#[test]
fn truncated() {
    let reg = Registry::new();
    let c = CancelToken::new();
    for p in files() {
        let data = std::fs::read(&p).unwrap();
        // Half-way through the entropy-coded data (the fuzz seed is a 239-byte 7×5 image).
        let head = specular_jpeg::read_info(&data).unwrap().header_len;
        let cut = head + (data.len() - head) / 2;
        let src = specular_core::Source::from_vec(&p, data[..cut].to_vec());
        let Ok(s) = reg.open(std::sync::Arc::new(src)) else {
            panic!("{}: cut file does not open", p.display());
        };
        let r = s.decode(&DecodeRequest::full(1), &c).unwrap();
        assert!(r.truncated, "{}", p.display());
        let req = DecodeRequest {
            prepare_regions: true,
            ..DecodeRequest::full(4)
        };
        let r = s.decode(&req, &c).unwrap();
        assert!(r.truncated, "{}", p.display());
    }
}
